/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE episodes (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    -- namespace: what kernel and what target
    kernel_name  TEXT NOT NULL,   -- e.g. "softmax", "matmul", "layer_norm"
    target       TEXT NOT NULL,   -- e.g. "ascend910_9589", "ascend950"
    -- Episode content fields
    observation  TEXT NOT NULL,   -- context and setup: what the kernel looked like, what the problem was
    thoughts     TEXT NOT NULL,   -- internal reasoning that led to the optimization approach
    action       TEXT NOT NULL,   -- what optimization was applied, how, in what format
    result       TEXT NOT NULL,   -- outcome: speedup achieved, what worked, what to try next time
    -- metadata
    created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S','now')),
    updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S','now'))
);
PRAGMA writable_schema=ON;
    observation,
    thoughts,
    action,
    result,
    content=''episodes'',
    content_rowid=''id''
)');
CREATE TABLE IF NOT EXISTS 'episodes_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'episodes_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'episodes_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'episodes_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE TRIGGER episodes_ai AFTER INSERT ON episodes BEGIN
    VALUES (new.id, new.observation, new.thoughts, new.action, new.result);
END;
CREATE TRIGGER episodes_au AFTER UPDATE ON episodes BEGIN
    VALUES ('delete', old.id, old.observation, old.thoughts, old.action, old.result);
    VALUES (new.id, new.observation, new.thoughts, new.action, new.result);
END;
CREATE TRIGGER episodes_ad AFTER DELETE ON episodes BEGIN
    VALUES ('delete', old.id, old.observation, old.thoughts, old.action, old.result);
END;
CREATE TRIGGER episodes_update_ts AFTER UPDATE ON episodes
FOR EACH ROW BEGIN
    UPDATE episodes SET updated_at = strftime('%Y-%m-%dT%H:%M:%S','now') WHERE id = OLD.id;
END;
CREATE INDEX idx_episodes_kernel  ON episodes (kernel_name);
CREATE INDEX idx_episodes_target  ON episodes (target);
CREATE INDEX idx_episodes_ns      ON episodes (kernel_name, target);
PRAGMA writable_schema=OFF;
COMMIT;
